scripts.王炜对话.txt:
	GetRandNum($wangwei,0,10);
	If ($wangwei == 0) @000;
	If ($wangwei == 1) @001;
	If ($wangwei == 2) @002;
	If ($wangwei == 3) @003;
	If ($wangwei == 4) @004;
	If ($wangwei == 5) @005;
	If ($wangwei == 6) @006;
	If ($wangwei == 7) @007;
	If ($wangwei == 8) @008;
	If ($wangwei == 9) @009;
	If ($wangwei == 10) @010;
	Return;

@000:
	Say("王炜：色不异空，空不异色，色即是空，空即是色。");
	Return;
	
@001:
	Say("王炜：三界无安，犹如火宅，众苦充满，甚可怖畏。",);
	Return;

@002:
	Say("王炜：真空不空，执相非真，破相亦非真。在世出世，徇俗是苦，绝俗亦是苦。",);
	Return;

@003:
	Say("王炜：物莫大于天地日月，而子美云：“日月笼中鸟，乾坤水上萍。”这是为什么呢？",);
	Return;

@004:
	Say("王炜：古人闲适处，今人却忙过了一生；古人实受处，今人又虚度了一世。",);
	Return;

@005:
	Say("王炜：古人闲适处，今人却忙过了一生；古人实受处，今人又虚度了一世。",);
	Return;

@006:
	Say("王炜：狐眠败砌，兔走荒台，尽是当年歌舞之地；露冷黄花，烟迷衰草，悉属旧时争战之场。盛衰何常，强弱安在，念此令人心灰。",);
	Return;

@007:
	Say("王炜：古之欲明明德於天下者先治其国。欲治其国者先齐其家。欲齐其家者先修其身。欲修其身者先正其心。欲正其心者先诚其意。欲诚其意者先致其知。致知在格物。物格而后知至。知至而后意诚。意诚而后心正。心正而后身修。身修而后家齐。家齐而后国治。国治而后天下平。",);
	Return;

@008:
	Say("王炜：道可道，非常道。名可名，非常名。",);
	Return;

@009:
	Say("王炜：天长地久。天地所以能长且久者，以其不自生，故能长生。",);
	Return;

@010:
	Say("王炜：小兄弟我们好像挺有缘分的，送你一本书吧。",);
	AddGoods("Book10-孤烟逐云.ini");
	Return;

scripts.蔷薇对话.txt:
	If ($Event == 1809) @1809;//结局2救月眉儿
	If ($Event == 1808) @1808;//结局2救月眉儿
	If ($Event == 540) @Label1;
	If ($Event == 550) @Label2;
	Return;


@1809:
	Say("蔷薇：影枫哥，你放心，我会让爹救月姑娘的。",29);
	Say("杨影枫：蔷薇……谢谢你",3);
	Return;

@1808:
	Say("杨影枫：蔷薇！终于找到你了！",3);
	FadeOut();
	Say("杨影枫给蔷薇讲了事情的经过……");
	DelNpc("蔷薇");
	AddNpc("蔷薇.ini",17,25,2);
	SetNpcKind("蔷薇",3);
	SetNpcScript("蔷薇","蔷薇对话.txt");
	FadeIn();
	Say("蔷薇：影枫哥，我爹太不讲理了！让我跟他说去……",29);
	Say("杨影枫：蔷薇……谢谢你能理解我",3);
	FadeOut();
	LoadMap("map_033_落叶谷.map");
	LoadNpc("map033.npc");
	LoadObj("map033_obj.obj");
	SetNpcKind("蔷薇",1);
	SetNpcPos("蔷薇",27,106);
	SetNpcDir("蔷薇",5);
	SetPlayerPos(27,107);
	SetPlayerDir(4);
	Say("二人回到落叶谷");
	FadeIn();
	Say("蔷薇：爹……你怎么能这样难为影枫哥呢？",31);
	Say("孟知秋：薇儿，我这还不都是为了你着想吗？",43);
	Say("蔷薇：我和影枫哥之间的事用不着你管，你快帮影枫哥救人吧。",31);
	Say("孟知秋：唉……真是女大不由爷呀……也罢……你们先回去休息吧，我今晚救人就是了。",42);
	Say("蔷薇：爹……你真好",30);
	Say("杨影枫：晚辈代月姑娘多谢前辈的救命之恩了",3);
	SetNpcKind("蔷薇",3);
	Assign($Event, 1809);
	SetMapTrap(1,"");
	Return;

@Label1:
	RunScript("事件55_1.txt");
	Return;

@Label2:
	If ($QiangWeiSense >= 20) @AddSenseEnd;
	Add($SenseVal, 5);
	Add($QiangWeiSense, 5);
@AddSenseEnd:
	Talk(10491, 10491);
	Return;

@end:
	Return;

scripts.蔷薇跟随对话.txt:
	If ($Event == 940) @Event940;
	
	Goto @end;
	
@Event940:
	If ($Result <> 3) @end;

	GetRandNum($QiangWeiTalk, 1, 7);
	If ($QiangWeiTalk == 1) @QiangWeiTalk1;
	If ($QiangWeiTalk == 2) @QiangWeiTalk2;
	If ($QiangWeiTalk == 3) @QiangWeiTalk3;
	If ($QiangWeiTalk == 4) @QiangWeiTalk4;
	If ($QiangWeiTalk == 5) @QiangWeiTalk5;
	If ($QiangWeiTalk == 6) @QiangWeiTalk6;
	If ($QiangWeiTalk == 7) @QiangWeiTalk7;
	@QiangWeiTalk1:
		Say("蔷薇：影枫哥，让我自己回去吧，你不要送了。", 32);
		Say("杨影枫：蔷薇，你一个人回去我不放心，还是我送你回去吧。", 2);
		Goto @end;
	@QiangWeiTalk2:
		Say("蔷薇：你喜欢的人是什么样子那？", 32);
		Say("杨影枫：她很善良，温柔。就像一朵水仙花。", 2);
		Say("蔷薇：真想见见她。", 32);
		Say("杨影枫：……", 5);
		Goto @end;
	@QiangWeiTalk3:
		Say("蔷薇：影枫哥，你不喜欢这里的冰雪吗？", 32);
		Goto @end;
	@QiangWeiTalk4:
		Say("蔷薇：我会怀念这里曾经发生过的事情。", 32);
		Goto @end;
	@QiangWeiTalk5:
		Say("蔷薇：影枫哥，我终于见到你啦！", 32);
		Say("杨影枫：蔷薇，你怎么自己出来找我，这样很危险。", 2);
		Say("蔷薇：影枫哥，我好想见到你！", 32);
		Say("杨影枫：蔷薇，我理解你的心情，可是……", 2);
		Goto @end;
	@QiangWeiTalk6:
		Say("杨影枫：蔷薇，你是个好姑娘，影枫哥对你就象对妹妹一样。", 2);
		Goto @end;
	@QiangWeiTalk7:
		Say("蔷薇：我会怀念这里曾经发生过的事情。", 32);
		Goto @end;
	
	Goto @end;
	
@end:
	Return;

